import{_ as a,o,c as t,a7 as i}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"Spendzo Privacy Policy","description":"Official Privacy Policy for the Spendzo application.","frontmatter":{"title":"Spendzo Privacy Policy","description":"Official Privacy Policy for the Spendzo application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/spendzo.md","filePath":"privacy/spendzo.md"}'),n={name:"privacy/spendzo.md"};function r(s,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy-for-spendzo" tabindex="-1">Privacy Policy for Spendzo <a class="header-anchor" href="#privacy-policy-for-spendzo" aria-label="Permalink to &quot;Privacy Policy for Spendzo&quot;">​</a></h1><p><strong>Effective Date:</strong> July 30, 2026<br><strong>Last Updated:</strong> July 30, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Spendzo is an offline-first personal expense and budget-tracking application. It is provided by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, telemetry, crash reporting, or cloud synchronization.</p><h2 id="information-stored-by-the-app" tabindex="-1">Information stored by the app <a class="header-anchor" href="#information-stored-by-the-app" aria-label="Permalink to &quot;Information stored by the app&quot;">​</a></h2><p>Spendzo stores information that you enter, including:</p><ul><li>Expenses, amounts, dates, categories, titles, notes, payment methods, and tags</li><li>Income entries, sources, amounts, dates, and notes</li><li>Budgets, savings targets, emergency allocations, and category limits</li><li>App preferences such as currency, budget-cycle dates, theme, and lock settings</li></ul><p>This information is stored locally in the app&#39;s private SQLite database on Android. The developer does not receive or have access to it.</p><h2 id="information-collected-or-shared" tabindex="-1">Information collected or shared <a class="header-anchor" href="#information-collected-or-shared" aria-label="Permalink to &quot;Information collected or shared&quot;">​</a></h2><p>Spendzo does not send your financial information or app usage information to the developer or third parties. It does not sell or share personal data.</p><p>The libraries used to provide the app interface, charts, local storage, and Android integration run within the app. No third-party analytics, advertising, or cloud-data SDK is included.</p><h2 id="pin-and-fingerprint-protection" tabindex="-1">PIN and fingerprint protection <a class="header-anchor" href="#pin-and-fingerprint-protection" aria-label="Permalink to &quot;PIN and fingerprint protection&quot;">​</a></h2><p>PIN protection is optional. Spendzo stores a cryptographic PIN verifier rather than the PIN itself. There is no PIN recovery.</p><p>Optional fingerprint unlock is handled by Android&#39;s biometric system. Spendzo does not receive or store fingerprint images or biometric templates. Android Keystore protects the local secret used for fingerprint unlock, and a PIN remains available as the fallback.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Spendzo may use:</p><ul><li><strong>Biometric permission:</strong> only when you choose fingerprint unlock.</li><li><strong>Internet permission:</strong> included for the Capacitor application runtime. The reviewed Spendzo app does not use it to upload or synchronize financial data.</li></ul><p>Spendzo does not request location, camera, microphone, contacts, SMS, or broad storage permissions. Android&#39;s system document picker is used when you choose where to save an export or backup.</p><h2 id="backups-and-exports" tabindex="-1">Backups and exports <a class="header-anchor" href="#backups-and-exports" aria-label="Permalink to &quot;Backups and exports&quot;">​</a></h2><p>You can create local <code>.budgetbackup</code>, CSV, and PDF files. These files are saved only to a location you select. Backup files exclude PIN and biometric secrets, but the financial information inside a backup is not encrypted. Anyone who can access an exported file may be able to read it.</p><p>Spendzo does not upload or retain copies of exported files. You are responsible for protecting and deleting files saved outside the app.</p><h2 id="data-retention-and-deletion" tabindex="-1">Data retention and deletion <a class="header-anchor" href="#data-retention-and-deletion" aria-label="Permalink to &quot;Data retention and deletion&quot;">​</a></h2><p>Local data remains on the device until you delete individual records, clear Spendzo&#39;s storage through Android settings, or uninstall the app. Files that you exported are separate and must be deleted from their saved locations.</p><p>Because Spendzo has no account or developer-operated server, there is no server-side account data for the developer to delete.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s privacy&quot;">​</a></h2><p>Spendzo is a general-purpose budgeting tool and is not specifically directed to children under 13. The developer does not knowingly collect personal information from children or other users.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to this policy&quot;">​</a></h2><p>This policy may be updated when Spendzo&#39;s features or data practices change. The updated date at the top will identify the latest version.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy questions, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',30)])])}const f=a(n,[["render",r]]);export{u as __pageData,f as default};
